// Leave the placeholder as it is to keep Google sign-in off (progress is then saved in the browser only).
window.CHESS_ASCENT_CONFIG = {
  googleClientId: 'PASTE_YOUR_CLIENT_ID.apps.googleusercontent.com'
};
